+#[inline]
+pub fn count_nqueens_conflicts(queens: &[usize]) -> usize {
+    let n = queens.len();
+    let mut conflicts = 0;
+    for r1 in 0..n {
+        for r2 in (r1 + 1)..n {
+            let c1 = queens[r1] as isize;
+            let c2 = queens[r2] as isize;
+            let dr = (r1 as isize - r2 as isize).abs();
+            if c1 == c2 || (c1 - c2).abs() == dr {
+                conflicts += 1;
+            }
+        }
+    }
+    conflicts
+}
