+            // Diagonal attack gradient + McWeeny cubic sharpening 2 P (1 - P) (1 - 2 P)
+            for r1 in 0..n {
+                for c1 in 0..n {
+                    let mut g_diag = 0.0;
+                    for r2 in 0..n {
+                        if r1 == r2 {
+                            continue;
+                        }
+                        let dr = (r1 as isize - r2 as isize).abs() as usize;
+                        if c1 + dr < n {
+                            g_diag += p[r2][c1 + dr];
+                        }
+                        if c1 >= dr {
+                            g_diag += p[r2][c1 - dr];
+                        }
+                    }
+                    let p_rc = p[r1][c1];
+                    let g_sharp = 2.0 * p_rc * (1.0 - p_rc) * (1.0 - 2.0 * p_rc);
+                    grad[r1][c1] = g_diag + 0.55 * g_sharp;
